DB.RW = DB.RW || {};
Object.assign(DB.RW, {
"enfuvirtide":{rl:"HIV fusion inhibitor given 90 mg (1 mL) subcutaneously twice daily per label with other antiretrovirals; injection site reactions occur in nearly all patients, and bacterial pneumonia is more frequent.",rh:"Fever, cough or dyspnea, an infected or abscessed injection site, or rash with fever, hypotension or rising liver enzymes typically prompt holding and provider notification.",ml:"gp41-binding HIV-1 fusion inhibitor labeled for treatment-experienced HIV-1 with ongoing replication despite antiretroviral therapy, in combination with other agents.",mp:"Mimics gp41 HR2 and binds HR1, preventing six-helix bundle formation and membrane fusion; acts extracellularly, unlike all other antiretrovirals except entry inhibitors such as maraviroc."},
"ledipasvir-sofosbuvir":{rl:"Harvoni one tablet (90 mg/400 mg) orally once daily for 12 weeks per label for genotype 1 treatment-naive HCV; HBV status is reviewed before starting, and amiodarone is a dangerous interaction.",rh:"Heart rate below 50, dizziness or syncope (especially with amiodarone), or jaundice and rising liver enzymes suggesting HBV reactivation typically prompt holding and provider notification.",ml:"NS5A inhibitor plus NS5B nucleotide polymerase inhibitor labeled for chronic HCV genotype 1, 4, 5 or 6 in adults and children 3 years and older, with ribavirin in decompensated cirrhosis or after transplant.",mp:"Sofosbuvir is a uridine nucleotide prodrug causing chain termination; with amiodarone it causes serious symptomatic bradycardia, and HBV reactivation is the class boxed warning."},
"anthrax-immune-globulin":{rl:"Anthrasil 420 units (7 vials) IV initially per label for inhalational anthrax with antibiotics, by slow pump infusion up to 2 mL/min; maltose falsely raises some glucose meter readings.",rh:"Hypotension, wheeze, chest pain, limb swelling, dyspnea, dark urine or falling urine output during or after infusion typically prompt stopping the infusion and provider notification.",ml:"Human polyclonal anti-protective antigen immune globulin labeled for inhalational anthrax in adults and children with antibacterial drugs, approved under the Animal Rule.",mp:"Boxed warnings: maltose glucose-meter interference causing iatrogenic hypoglycemia, and thrombosis, both class effects of maltose-containing IVIG products."},
"obiltoxaximab":{rl:"Anthim 16 mg/kg IV single dose over 90 minutes per label after diphenhydramine premedication, given with antibiotics; anaphylaxis boxed warning.",rh:"Urticaria, pruritus, wheeze, stridor, throat tightness or hypotension during infusion typically prompt stopping the infusion and provider notification.",ml:"Chimeric IgG1 monoclonal antibody against B. anthracis protective antigen labeled for treatment of inhalational anthrax with antibiotics and for prophylaxis when alternatives are unavailable or inappropriate.",mp:"Blocks protective antigen binding to ANTXR receptors, preventing entry of lethal factor and edema factor; approved under the FDA Animal Rule like raxibacumab."},
"brincidofovir":{rl:"Tembexa 200 mg orally once weekly for 2 doses per label for smallpox in patients 48 kg or more; diarrhea and liver enzyme elevation are common, and longer use increased mortality.",rh:"Severe diarrhea or vomiting, jaundice, or ALT, AST or bilirubin well above baseline typically prompt holding and provider notification.",ml:"Oral lipid-conjugated cidofovir prodrug labeled for human smallpox in adults and children including neonates, approved under the Animal Rule.",mp:"Intracellular cidofovir diphosphate inhibits orthopoxvirus DNA polymerase; lipid conjugation bypasses OAT1, so it is far less nephrotoxic than IV cidofovir."},
"emtricitabine-tenofovir-disoproxil":{rl:"Truvada one tablet (200 mg/300 mg) orally once daily per label for HIV-1 treatment with other antiretrovirals or as PrEP after a negative HIV test; kidney, bone and HBV flare risks.",rh:"Positive or unknown HIV status in a PrEP patient, falling creatinine clearance, glycosuria or proteinuria, bone pain or fracture, or jaundice after stopping typically prompt provider notification.",ml:"NRTI combination labeled for HIV-1 treatment (17 kg or more) with other agents and for HIV-1 PrEP in at-risk adults and adolescents 35 kg or more.",mp:"Tenofovir disoproxil causes proximal tubulopathy (Fanconi syndrome) and bone loss; emtricitabine shares the M184V mutation with lamivudine."},
"dolutegravir-lamivudine":{rl:"Dovato one tablet (50 mg/300 mg) orally once daily per label as a complete HIV-1 regimen; HBV testing before starting, cation spacing, and no dofetilide.",rh:"Rash with fever or blistering, jaundice or rising liver enzymes, depression or suicidal thoughts, or symptoms of lactic acidosis typically prompt holding and provider notification.",ml:"INSTI plus NRTI two-drug complete regimen labeled for HIV-1 in adults and adolescents 12 years and older (at least 25 kg) who are treatment-naive or suppressed without resistance.",mp:"Dolutegravir inhibits OCT2, raising serum creatinine without true GFR change and increasing metformin levels; integrase inhibitors chelate polyvalent cations."}
});

