DB.RW = DB.RW || {};
Object.assign(DB.RW, {
"flurazepam":{rl:"Schedule IV long-acting benzodiazepine hypnotic; label initial dose 15 mg in women and 15 or 30 mg in men, limited to 15 mg in elderly patients; boxed warnings for opioid co-use, misuse and withdrawal.",rh:"Excess sedation, slowed breathing, new confusion or falls typically prompt holding and notifying the provider.",ml:"Long-acting benzodiazepine labeled for insomnia with difficulty falling or staying asleep; active metabolite N1-desalkylflurazepam has a 47 to 100 hour half-life.",mp:"Accumulation of the long-lived metabolite causes daytime hangover; benzodiazepines are on the Beers list for older adults; flumazenil reverses."},
"tasimelteon":{rl:"Melatonin MT1/MT2 agonist; 20 mg one hour before bedtime at the same time nightly without food per label; somnolence is the main safety issue.",rh:"Marked daytime somnolence or use with fluvoxamine or rifampin typically prompts notifying the provider.",ml:"MT1/MT2 agonist labeled for Non-24 in adults and nighttime sleep disturbances in Smith-Magenis syndrome (capsules 16 and older, suspension ages 3 to 15).",mp:"Non-24 occurs mainly in totally blind patients without light input to the SCN; CYP1A2 inhibition by fluvoxamine raises exposure markedly."},
"chlorzoxazone":{rl:"Centrally acting muscle relaxant; 500 mg three or four times daily per label, increased to 750 mg if needed; sedation and rare hepatotoxicity.",rh:"Jaundice, dark urine, right upper quadrant pain or excessive sedation typically prompt holding and notifying the provider.",ml:"Benzoxazolone muscle relaxant labeled as an adjunct for acute painful musculoskeletal conditions; acts on spinal and subcortical multisynaptic reflexes.",mp:"Classic CYP2E1 probe substrate; harmless orange to purple-red urine; rare idiosyncratic fatal hepatotoxicity."},
"inebilizumab":{rl:"Anti-CD19 IV infusion: 300 mg, a second 300 mg 2 weeks later, then 300 mg every 6 months per label, with premedication; HBV, TB and immunoglobulin screening precede treatment.",rh:"Infusion reaction signs, fever or active infection, or new neurologic deficits typically prompt holding the infusion and notifying the provider.",ml:"Afucosylated anti-CD19 B-cell depleting antibody labeled for AQP4-positive NMOSD, IgG4-related disease and AChR or MuSK positive gMG.",mp:"CD19 is present on plasmablasts that lack CD20, so inebilizumab depletes more antibody-producing cells than anti-CD20 agents."},
"satralizumab":{rl:"Anti-IL-6 receptor SC injection: 120 mg at weeks 0, 2 and 4, then every 4 weeks per label; HBV, TB and liver tests precede treatment.",rh:"Signs of active infection, jaundice or a significant liver enzyme rise typically prompt holding the dose and notifying the provider.",ml:"Humanized recycling anti-IL-6 receptor antibody labeled for AQP4 antibody-positive NMOSD in adults.",mp:"pH-dependent IL-6R binding lets the antibody recycle via FcRn; IL-6 blockade masks fever and CRP during infection."},
"methsuximide":{rl:"Succinimide anticonvulsant; 300 mg per day for the first week, increased weekly by 300 mg per day to 1.2 g per day per label; blood dyscrasias and SLE are key warnings.",rh:"Fever, sore throat, bruising, rash or excessive drowsiness typically prompt holding and notifying the provider.",ml:"Succinimide T-type calcium channel blocker labeled for absence seizures refractory to other drugs.",mp:"Activity comes largely from N-desmethylmethsuximide with a 28 to 80 hour half-life; it can raise phenytoin and phenobarbital levels."},
"zilucoplan":{rl:"Daily SC peptide C5 inhibitor dosed by weight band (16.6, 23 or 32.4 mg) per label; boxed meningococcal infection warning with REMS and prior vaccination.",rh:"Fever, headache with stiff neck, rash, abdominal pain suggestive of pancreatitis or worsening bulbar weakness typically prompt holding and notifying the provider.",ml:"Macrocyclic peptide complement C5 inhibitor labeled for AChR antibody-positive generalized myasthenia gravis in adults.",mp:"Terminal complement blockade markedly raises Neisseria meningitidis risk; unlike eculizumab, it is self-injected daily."},
"nipocalimab":{rl:"Anti-FcRn IV infusion: 30 mg/kg over at least 30 minutes, then 15 mg/kg over at least 15 minutes every 2 weeks per label for gMG.",rh:"Hypersensitivity signs, infusion reactions or active serious infection typically prompt holding the infusion and notifying the provider.",ml:"Aglycosylated anti-FcRn antibody labeled for AChR or MuSK positive gMG and warm autoimmune hemolytic anemia in patients 12 and older.",mp:"FcRn blockade shortens IgG half-life and also speeds clearance of IVIG and other IgG-based drugs."},
"dihydroergotamine-nasal":{rl:"Ergot nasal spray: 0.5 mg in each nostril, repeated in 15 minutes for 2 mg total per label; boxed warning for ischemia with potent CYP3A4 inhibitors.",rh:"Chest pain, cold or numb extremities, focal neurologic deficits or elevated blood pressure typically prompt holding and notifying the provider.",ml:"Ergot 5-HT1B/1D agonist nasal spray labeled for acute treatment of migraine with or without aura.",mp:"Contraindicated within 24 hours of triptans, in pregnancy and with CYP3A4 inhibitors; low headache recurrence from slow receptor dissociation."},
"daxibotulinumtoxin":{rl:"Botulinum toxin type A IM: 40 Units for glabellar lines or 125 to 250 Units for cervical dystonia per label, no more often than every 3 months; boxed distant spread warning.",rh:"Swallowing difficulty, breathing difficulty, generalized weakness or voice change after injection typically prompt urgent provider notification.",ml:"Peptide-formulated botulinum toxin type A labeled for moderate to severe glabellar lines and cervical dystonia in adults.",mp:"Cleaves SNAP-25 to block acetylcholine release; units are not interchangeable with other botulinum products."}
});

