DB.RW = DB.RW || {};
Object.assign(DB.RW, {
"zileuton":{rl:"Oral 5-lipoxygenase inhibitor for asthma, 600 mg four times a day per the ZYFLO label; ALT is reviewed before and regularly during the first year, and theophylline levels rise when combined.",rh:"Jaundice, dark urine, right upper quadrant pain, ALT above 5 times ULN, new mood or behavior changes or worsening asthma typically prompt holding and notifying the provider.",ml:"Leukotriene synthesis inhibitor labeled for prophylaxis and chronic treatment of asthma in patients 12 and older; contraindicated in active liver disease.",mp:"Zileuton inhibits 5-lipoxygenase (blocking LTB4 and cysteinyl leukotriene synthesis), whereas montelukast and zafirlukast antagonize CysLT1; it inhibits CYP1A2 and roughly doubles theophylline levels."},
"mometasone-formoterol":{rl:"ICS/LABA metered-dose inhaler, 2 inhalations of 100/5 or 200/5 mcg twice daily per label (50/5 mcg in children 5 to 11); maintenance only, with thrush and beta-agonist effects as known risks.",rh:"Worsening breathing despite rescue use, palpitations, tremor or signs of low potassium typically prompt notifying the provider.",ml:"Mometasone furoate plus formoterol, labeled for twice-daily treatment of asthma in patients 5 years and older; not for acute bronchospasm.",mp:"In asthma, LABAs are paired with an inhaled corticosteroid because LABA monotherapy is associated with asthma-related death."},
"fluticasone-furoate-vilanterol":{rl:"Once-daily ICS/LABA dry powder inhaler; 1 inhalation of 100/25 mcg once daily for COPD per label and 100/25 or 200/25 mcg for adult asthma; not a rescue inhaler.",rh:"Fever with productive cough in COPD, worsening dyspnea despite rescue use, palpitations or oral thrush typically prompt notifying the provider.",ml:"Fluticasone furoate plus vilanterol, labeled for COPD maintenance and for asthma maintenance in patients 5 years and older.",mp:"Inhaled corticosteroids in COPD increase pneumonia risk and benefit mainly patients with frequent exacerbations and higher blood eosinophils per GOLD."},
"budesonide-glycopyrrolate-formoterol":{rl:"Triple ICS/LAMA/LABA inhaler, 2 inhalations twice daily per label (160/9/4.8 mcg for COPD, 160/18/4.8 mcg for asthma from age 12); shaken before use.",rh:"Eye pain or halos, urinary retention, fever with cough, palpitations or worsening breathing typically prompt holding and notifying the provider.",ml:"Budesonide, glycopyrrolate and formoterol, labeled for COPD maintenance in adults and asthma maintenance in patients 12 and older.",mp:"GOLD reserves triple therapy for COPD with exacerbations on LAMA/LABA, particularly with blood eosinophils of 300 or higher; the LAMA component adds glaucoma and urinary retention risk."},
"glycopyrrolate-formoterol":{rl:"LAMA/LABA metered-dose inhaler for COPD, 2 inhalations twice daily per label (glycopyrrolate 18 mcg and formoterol 9.6 mcg per dose); not for asthma or rescue.",rh:"Eye pain or halos, inability to urinate, palpitations or worsening breathing typically prompt holding and notifying the provider.",ml:"Glycopyrrolate plus formoterol, labeled for maintenance treatment of COPD; not indicated for asthma or acute bronchospasm.",mp:"LAMAs block M3 receptors on airway smooth muscle while LABAs stimulate beta-2 receptors, giving additive bronchodilation; LABA without ICS is not used in asthma."},
"albuterol-budesonide":{rl:"As-needed SABA/ICS rescue inhaler for adults with asthma, 2 inhalations per dose and no more than 6 doses in 24 hours per label; frequent use reflects poor control.",rh:"Rising rescue use, lack of relief, palpitations, tremor or signs of low potassium typically prompt notifying the provider.",ml:"Albuterol plus budesonide, labeled for as-needed treatment or prevention of bronchoconstriction and reduction of exacerbation risk in asthma in patients 18 and older.",mp:"Adding an inhaled corticosteroid to every reliever dose reduces severe exacerbations compared with albuterol alone, consistent with GINA anti-inflammatory reliever concepts."},
"tiotropium-olodaterol":{rl:"Once-daily LAMA/LABA soft mist inhaler for COPD, 2 inhalations once daily per label; not for acute symptoms or asthma.",rh:"Eye pain or halos, urinary retention, palpitations or worsening breathing typically prompt holding and notifying the provider.",ml:"Tiotropium plus olodaterol, labeled for long-term once-daily maintenance treatment of COPD including chronic bronchitis and emphysema.",mp:"Tiotropium has kinetic M3 selectivity with slow receptor dissociation, allowing once-daily dosing, and is renally excreted."},
"umeclidinium-vilanterol":{rl:"Once-daily LAMA/LABA dry powder inhaler for COPD, 1 inhalation of 62.5/25 mcg per label; not for asthma or rescue.",rh:"Eye pain or halos, urinary retention, palpitations or worsening breathing typically prompt holding and notifying the provider.",ml:"Umeclidinium plus vilanterol, labeled for maintenance treatment of COPD; not indicated for acute bronchospasm or asthma.",mp:"LAMA/LABA combinations improve lung function and dyspnea in COPD more than either component alone; anticholinergic risks include angle-closure glaucoma and urinary retention."},
"aclidinium-formoterol":{rl:"Twice-daily LAMA/LABA dry powder inhaler for COPD, 1 inhalation of 400/12 mcg twice daily per label; not for asthma or rescue.",rh:"Eye pain or halos, urinary retention, palpitations or worsening breathing typically prompt holding and notifying the provider.",ml:"Aclidinium bromide plus formoterol fumarate, labeled for maintenance treatment of COPD; not indicated for acute bronchospasm or asthma.",mp:"Aclidinium is rapidly hydrolyzed by plasma esterases to inactive metabolites, so systemic anticholinergic exposure is low."}
});

