Object.assign(DB.RW, {
"methazolamide":{rl:"Oral carbonic anhydrase inhibitor dosed 50 to 100 mg two or three times daily per label for glaucoma; sulfonamide reactions, hypokalemia and metabolic acidosis are the key safety issues.",rh:"Rash, sore throat, fever, unusual bruising, confusion, low potassium or sodium, or rapid breathing from acidosis typically prompt holding and notifying the provider.",ml:"Sulfonamide carbonic anhydrase inhibitor labeled for open-angle and secondary glaucoma and preoperatively in acute angle-closure glaucoma.",mp:"Longer half-life and more hepatic metabolism than acetazolamide, with fewer kidney stones; still causes normal anion gap metabolic acidosis and paresthesias."},
"ganciclovir-ophthalmic":{rl:"Ganciclovir 0.15% gel, 1 drop 5 times daily until the corneal ulcer heals, then 3 times daily for 7 days per label; contact lenses are not worn during infection.",rh:"Worsening eye pain, spreading ulcer, decreased vision or use of a steroid drop typically prompt notifying the eye provider.",ml:"Topical guanosine analog antiviral labeled for acute herpetic keratitis (dendritic ulcers) in adults and children 2 years and older.",mp:"Activated by HSV thymidine kinase in infected cells; dendritic ulcer with terminal bulbs on fluorescein is the classic finding, and steroids worsen epithelial HSV keratitis."},
"trifluridine-ophthalmic":{rl:"Trifluridine 1% drops every 2 hours while awake (maximum 9 per day) until re-epithelialization, then every 4 hours for 7 days per label; use beyond 21 days is avoided.",rh:"No improvement by 7 days, incomplete healing by 14 days, or signs of epithelial toxicity typically prompt notifying the eye provider.",ml:"Topical thymidine analog antiviral labeled for primary keratoconjunctivitis and recurrent epithelial keratitis from HSV types 1 and 2.",mp:"Inhibits thymidylate synthase and is incorporated into DNA; it is nonselective, so prolonged use injures corneal epithelium."},
"natamycin":{rl:"Natamycin 5% suspension, shaken well, 1 drop hourly or every 2 hours initially and tapered to 6 to 8 times daily after 3 to 4 days for 14 to 21 days per label for fungal keratitis.",rh:"Enlarging infiltrate, increasing pain, decreasing vision or no improvement after about a week typically prompt notifying the eye provider.",ml:"Polyene antifungal suspension labeled for fungal blepharitis, conjunctivitis and keratitis, including Fusarium solani keratitis.",mp:"Only FDA-approved topical ophthalmic antifungal; superior to topical voriconazole for Fusarium keratitis in MUTT I; binds ergosterol without forming pores."},
"dexamethasone-intravitreal-implant":{rl:"Ozurdex is a 0.7 mg biodegradable dexamethasone implant injected into the vitreous under aseptic conditions; pressure and endophthalmitis signs are monitored afterward per label.",rh:"Eye pain, worsening redness, light sensitivity, decreasing vision or a raised eye pressure after injection typically prompt urgent notification of the ophthalmologist.",ml:"Intravitreal corticosteroid implant labeled for macular edema after branch or central retinal vein occlusion, noninfectious posterior uveitis and diabetic macular edema.",mp:"Contraindicated with a torn posterior lens capsule because the implant can migrate into the anterior chamber; cataract and steroid-induced ocular hypertension are class effects."},
"fluocinolone-intravitreal-implant":{rl:"Iluvien is a 0.19 mg nonbioerodible fluocinolone implant releasing 0.25 mcg/day initially for 36 months per label; long-term eye pressure follow-up is standard.",rh:"Eye pain, worsening redness, decreasing vision or a raised eye pressure after injection typically prompt urgent notification of the ophthalmologist.",ml:"Intravitreal corticosteroid implant labeled for DME after a steroid course without significant pressure rise and for chronic noninfectious posterior uveitis.",mp:"Lasts about 3 years and does not dissolve, unlike Ozurdex; high rates of cataract and steroid-induced pressure rise, sometimes needing glaucoma surgery."},
"cenegermin":{rl:"Cenegermin 0.002%, 1 drop 6 times daily at 2-hour intervals for 8 weeks per label, one vial per day; other drops are spaced at least 15 minutes apart.",rh:"Signs of eye infection, marked inflammation or a worsening corneal defect typically prompt notifying the ophthalmologist.",ml:"Recombinant human nerve growth factor eye drop labeled for neurotrophic keratitis in adults and children.",mp:"Acts on TrkA and p75 receptors; neurotrophic keratitis results from trigeminal (CN V1) sensory loss after herpes zoster, diabetes or neurosurgery."},
"oxymetazoline-ophthalmic":{rl:"Oxymetazoline 0.1%, 1 drop into one or both ptotic eyes once daily per label; single-use containers are discarded after dosing.",rh:"Sudden new ptosis, double vision, pupil asymmetry, eye pain with halos, or a marked blood pressure change typically prompt notifying the provider.",ml:"Ophthalmic alpha adrenergic agonist labeled for acquired blepharoptosis in adults.",mp:"Contracts the sympathetically innervated superior tarsal (Mueller) muscle; the levator is CN III, so Horner syndrome causes only mild ptosis."},
"acoltremon":{rl:"Acoltremon 0.003%, 1 drop in each eye twice daily about 12 hours apart per label; instillation site pain affects about half of patients.",rh:"Severe or persistent eye pain, vision change or signs of eye infection typically prompt notifying the provider.",ml:"First-in-class TRPM8 agonist eye drop labeled for the signs and symptoms of dry eye disease (approved 2025).",mp:"Stimulates TRPM8 cold thermoreceptors on corneal trigeminal nerves to raise basal tear production; TRPM8 is the menthol receptor."}
});

