Object.assign(DB.RW, {
"sutimlimab":{rl:"IV C1s inhibitor given 6,500 mg (39 to less than 75 kg) or 7,500 mg (75 kg or more) weekly for 2 weeks then every 2 weeks per label; encapsulated bacterial infection and infusion reactions are the key risks.",rh:"Fever, signs of infection, or an infusion-related reaction typically prompt holding and notifying the provider.",ml:"Humanized anti-C1s monoclonal antibody labeled for hemolysis in adults with cold agglutinin disease.",mp:"Cold agglutinin disease is IgM-driven, classical complement-mediated extravascular hemolysis; blocking C1s spares the alternative and lectin pathways."},
"pegunigalsidase-alfa":{rl:"PEGylated alpha-galactosidase A ERT given 1 mg/kg (actual body weight) IV every 2 weeks per label; boxed warning for hypersensitivity and anaphylaxis.",rh:"Rash, wheeze, hypotension or swelling during infusion typically prompt pausing the infusion and notifying the provider.",ml:"Cross-linked PEGylated recombinant alpha-galactosidase A labeled for adults with confirmed Fabry disease.",mp:"Fabry disease is X-linked GLA deficiency with Gb3 accumulation causing acroparesthesias, angiokeratomas, hypohidrosis, LVH, stroke and renal failure."},
"olipudase-alfa":{rl:"Acid sphingomyelinase ERT started at 0.1 mg/kg (adults) and escalated to 3 mg/kg IV every 2 weeks per label; transaminases are reviewed during escalation; boxed warning for anaphylaxis.",rh:"Elevated transaminases, hypersensitivity symptoms, or a possible pregnancy typically prompt holding and notifying the provider.",ml:"Recombinant acid sphingomyelinase labeled for non-CNS manifestations of ASMD in adults and children.",mp:"Slow dose escalation limits toxic ceramide and sphingomyelin breakdown products; the drug does not cross the blood-brain barrier."},
"velmanase-alfa":{rl:"Alpha-mannosidase ERT given 1 mg/kg IV weekly per label, infused over at least 60 minutes or capped at 25 mL/hour in larger patients; boxed warning for anaphylaxis.",rh:"Rash, wheeze, hypotension or swelling during infusion typically prompt pausing the infusion and notifying the provider.",ml:"Recombinant human alpha-mannosidase labeled for non-CNS manifestations of alpha-mannosidosis in adults and children.",mp:"Alpha-mannosidosis is an autosomal recessive MAN2B1 lysosomal storage disease with hearing loss, intellectual disability and immune deficiency."},
"palovarotene":{rl:"Oral RAR-gamma agonist given 5 mg daily, with 20 mg daily for 4 weeks then 10 mg daily for 8 weeks at flare-ups per label (14 years and older); teratogenic, with premature epiphyseal closure in children.",rh:"A positive pregnancy test, new mood symptoms, or growth plate concerns in a child typically prompt holding and notifying the provider.",ml:"Retinoid labeled to reduce new heterotopic ossification in fibrodysplasia ossificans progressiva; boxed warnings for embryo-fetal toxicity and premature epiphyseal closure.",mp:"FOP is caused by activating ACVR1 (ALK2) mutations; malformed great toes at birth and trauma-triggered flare-ups are classic."},
"mavorixafor":{rl:"Oral CXCR4 antagonist given 400 mg (over 50 kg) or 300 mg (50 kg or less) once daily after an overnight fast per label; QTc prolongation and CYP2D6 interactions are key.",rh:"QTc prolongation, palpitations or syncope, fever, or a possible pregnancy typically prompt holding and notifying the provider.",ml:"CXCR4 antagonist labeled for WHIM syndrome in patients 12 years and older to raise circulating mature neutrophils and lymphocytes.",mp:"WHIM syndrome stems from gain-of-function CXCR4 mutations causing myelokathexis; plerixafor uses the same receptor for stem cell mobilization."},
"sebetralstat":{rl:"Oral plasma kallikrein inhibitor taken as 600 mg at attack onset, with a second 600 mg dose at least 3 hours later if needed, up to 1,200 mg in 24 hours per label.",rh:"Throat tightness, voice change or stridor during an attack is an airway emergency regardless of oral dosing and typically prompts urgent provider notification.",ml:"First oral on-demand therapy labeled for acute attacks of hereditary angioedema in patients 12 years and older.",mp:"HAE swelling is bradykinin mediated with low C4 and no urticaria, so epinephrine and antihistamines are less effective."},
"ecallantide":{rl:"SC plasma kallikrein inhibitor given as 30 mg (three 10 mg injections) by a healthcare professional per label, with one more 30 mg dose within 24 hours if the attack persists; boxed warning for anaphylaxis.",rh:"Itching, wheeze, hypotension or throat tightness after dosing typically prompt urgent provider notification as possible anaphylaxis.",ml:"Recombinant Kunitz-domain plasma kallikrein inhibitor labeled for acute HAE attacks in patients 12 years and older.",mp:"Anaphylaxis risk limits ecallantide to healthcare professional administration, unlike self-injected icatibant."},
"garadacimab":{rl:"Anti-FXIIa monoclonal antibody given as a 400 mg SC loading dose then 200 mg SC monthly per label for HAE prophylaxis; aPTT can be prolonged by assay interference.",rh:"A breakthrough attack with throat symptoms or a hypersensitivity reaction after injection typically prompts urgent provider notification.",ml:"First activated factor XII inhibitor, labeled for prophylaxis of HAE attacks in patients 12 years and older.",mp:"Factor XII deficiency prolongs the aPTT without bleeding, which is why FXIIa inhibition prevents bradykinin generation without hemorrhage."},
"donidalorsen":{rl:"Prekallikrein antisense oligonucleotide given 80 mg SC every 4 weeks, or every 8 weeks, per label for HAE prophylaxis; hypersensitivity is the key labeled risk.",rh:"Rash, swelling or breathing difficulty after injection, or a breakthrough attack with throat symptoms, typically prompts urgent provider notification.",ml:"GalNAc-conjugated antisense oligonucleotide labeled for prophylaxis of HAE attacks in patients 12 years and older.",mp:"The -orsen suffix marks antisense oligonucleotides; GalNAc conjugation directs them to hepatocytes through the asialoglycoprotein receptor."}
});

