Object.assign(DB.LABEL, {
"luspatercept":{"s":"82f4d266-3f52-41eb-86ba-0abf3cf468e8","d":"2026-02-27","b":"Reblozyl (luspatercept-aamt)","m":"Celgene Corporation","r":"SUBCUTANEOUS","q":[["Beta thalassemia","The recommended starting dose of REBLOZYL is 1 mg/kg once every 3 weeks by subcutaneous injection for patients with beta thalassemia."],["MDS","The recommended starting dosage of REBLOZYL is 1 mg/kg once every 3 weeks by subcutaneous injection for the treatment of anemia of MDS."],["Maximum (beta thalassemia)","Do not increase the dose beyond the maximum dose of 1.25 mg/kg."]],"nl":0},
"zoledronic-acid":{"s":"1738a682-5903-b675-3a7a-61d299a6f248","d":"2023-10-30","b":"Zoledronic Acid Injection 4 mg/5 mL (generic of Zometa)","m":"Dr. Reddy's Laboratories Limited","r":"INTRAVENOUS","q":[["Hypercalcemia of malignancy","The maximum recommended dose of zoledronic acid injection in hypercalcemia of malignancy (albumin-corrected serum calcium greater than or equal to 12 mg/dL [3.0 mmol/L]) is 4 mg. The 4 mg dose must be given as a single-dose intravenous infusion over no less than 15 minutes."],["Myeloma and bone metastases","The recommended dose of zoledronic acid injection in patients with multiple myeloma and metastatic bone lesions from solid tumors for patients with creatinine clearance (CrCl) greater than 60 mL/min is 4 mg infused over no less than 15 minutes every 3 to 4 weeks."],["Calcium and vitamin D","Patients should also be administered an oral calcium supplement of 500 mg and a multiple vitamin containing 400 international units of vitamin D daily."]],"nl":0},
"pamidronate":{"s":"c2ca033e-fa5f-4141-b702-11f8b4303da1","d":"2025-12-15","b":"Pamidronate Disodium Injection","m":"Mylan Institutional LLC","r":"INTRAVENOUS","q":[["Moderate hypercalcemia","The recommended dose of pamidronate disodium in moderate hypercalcemia (corrected serum calcium* of approximately 12 mg/dL to 13.5 mg/dL) is 60 mg to 90 mg given as a single-dose, intravenous infusion over 2 hours to 24 hours."],["Severe hypercalcemia","The recommended dose of pamidronate disodium in severe hypercalcemia (corrected serum calcium* > 13.5 mg/dL) is 90 mg given as a single-dose, intravenous infusion over 2 to 24 hours."],["Bone metastases","The recommended dose of pamidronate disodium in patients with osteolytic bone metastases is 90 mg administered over a 2-hour infusion given every 3 to 4 weeks."]],"nl":0},
"crotalidae-polyvalent-immune-fab":{"s":"77abd784-3387-420d-abdc-4fe97215d233","d":"2026-04-13","b":"CroFab (crotalidae polyvalent immune fab, ovine)","m":"BTG International Inc.","r":"INTRAVENOUS","q":[["Initial","Based on clinical experience with CROFAB, the recommended initial dose is 4 to 6 vials; however, the starting dose may vary from a minimum of 4 vials to a maximum of 12 vials based on clinical judgment and severity of envenomation [3]."],["Repeat","If initial control is not achieved by the first dose, an additional dose of 4 to 6 vials should be administered repeatedly until initial control of the envenomation syndrome has been achieved."],["Maintenance","Once initial control has been achieved, additional 2-vial doses of CROFAB every 6 hours for up to 18 hours (3 doses) are recommended."]],"nl":0},
"crotalidae-immune-fab2-equine":{"s":"a16596a5-e87e-40c2-8e34-cea5839849c3","d":"2026-01-23","b":"Anavip (crotalidae immune F(ab')2, equine)","m":"Rare Disease Therapeutics, Inc.","r":"INTRAVENOUS","q":[["Initial","The initial dose of ANAVIP is 10 vials."],["Additional","Administer additional 10 vial doses if needed to arrest the progressive symptoms and repeat every hour until local signs of envenomation are not progressing, systemic symptoms are resolved and coagulation parameters have normalized or are trending toward normal."],["Recurrence","Re-emerging symptoms including coagulopathies may be suppressed with additional 4 vial doses of ANAVIP as needed."],["Pediatric","Fluid volumes may need to be adjusted for very small children or infants."]],"nl":0},
"north-american-coral-snake-antivenin":{"s":"6d0f94b4-82ca-37c7-edb0-4f0702cf6c8d","d":"2022-11-22","b":"North American Coral Snake Antivenin (Equine)","m":"Wyeth Pharmaceuticals LLC (Pfizer)","r":"INTRAVENOUS","q":[["Adult","In adults and adolescents, the dose may vary from 3 to 5 vials, depending on the response to treatment."],["Rate","Infuse the first 1 or 2 mL over a 3- to 5-minute period, observing for allergic reaction."],["Pediatric","For small children, allow the first 100 mL to run in rapidly but then decrease to a rate not to exceed 4 mL per minute."]],"nl":0},
"black-widow-spider-antivenin":{"s":"600e54ad-af13-462f-8a2d-2c3f7d91a8cd","d":"2024-10-08","b":"Antivenin (Latrodectus mactans) (Black Widow Spider Antivenin, equine)","m":"Merck Sharp & Dohme LLC","r":"INTRAMUSCULAR; INTRAVENOUS","q":[["Adult and pediatric","The dose for adults and children is the entire contents of a restored single-dose vial (2.5 mL) of Antivenin."],["IV","Antivenin also may be given intravenously in 10 to 50 mL of saline solution over a 15 minute period."],["IV preference","It is the preferred route in severe cases, or when the patient is under 12, or in shock."]],"nl":0},
"centruroides-scorpion-immune-fab2":{"s":"5cb65048-a30c-48e5-8bc8-897983d08068","d":"2025-07-16","b":"Anascorp (centruroides (scorpion) immune F(ab')2, equine)","m":"Rare Disease Therapeutics, Inc.","r":"INTRAVENOUS","q":[["Initial","The initial dose of ANASCORP is 3 vials."],["Infusion","Infuse intravenously over 10 minutes."],["Additional","Administer one vial at a time at 30-60 minute intervals."],["Pediatric","The efficacy and safety of ANASCORP is comparable in pediatric and adult patients."]],"nl":0}
});
