DB.FLAGS = [{"area": "FDA label alignment", "sev": "high", "t": "drug", "ref": "theophylline", "text": "Adult and pediatric dose titration tables were never read from the label (too long to fetch). Only the 400 mg/day cap for patients over 60 was added; the rest is DrugBug's old text.", "date": "2026-10-07", "id": "f001"}, {"area": "FDA label alignment", "sev": "high", "t": "drug", "ref": "nitroglycerin", "text": "IV infusion numbers (10-200 mcg/min, 200-400 mcg/min max, titration steps) were not checked against the IV label (openFDA rate-limited).", "date": "2026-10-07", "id": "f002"}, {"area": "FDA label alignment", "sev": "high", "t": "drug", "ref": "midazolam", "text": "ICU infusion field left unchanged; the fetched label value (0.04-0.2 mg/kg/h maintenance) did not match expectations (0.02-0.1). Verify against the label.", "date": "2026-10-07", "id": "f003"}, {"area": "FDA label alignment", "sev": "high", "t": "drug", "ref": "paclitaxel", "text": "Dosing came from the 2011 Taxol label and the Abraxane label, not the generic label on file (setid ea28753a). Weekly 80 mg/m2 marked off-label; famotidine 'commonly substituted' in premedication.", "date": "2026-10-07", "id": "f004"}, {"area": "FDA label alignment", "sev": "high", "t": "drug", "ref": "reteplase", "text": "Marked 'No current US FDA label' only because it was not found in openFDA or DailyMed. Retavase may still be FDA approved. Confirm before launch.", "date": "2026-10-07", "id": "f005"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "mebendazole", "text": "The 100 mg Emverm label's product code is inactive (may be discontinued). Doses came from a DailyMed search summary; no setid recorded.", "date": "2026-10-07", "id": "f006"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "methadone", "text": "Label gives no fixed pain starting dose, so DrugBug's '2.5-10 mg every 8-12 h' was removed. Consider adding a guideline starting dose marked off-label.", "date": "2026-10-07", "id": "f007"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "vecuronium", "text": "Maximum Dose field now says 0.28 mg/kg, which the label only reports as 'have been used', not a stated maximum.", "date": "2026-10-07", "id": "f008"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "epinephrine", "text": "Auto-injector weight bands (0.15 mg for 15-30 kg, 0.3 mg for 30 kg or more) came from memory of the EpiPen label; that label was not fetched. Quiz line changed to match.", "date": "2026-10-07", "id": "f009"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "dexmedetomidine", "text": "The label fetched now covers pediatric procedural sedation (1 month to under 18), contradicting the earlier check. Pediatric doses were added from it; ICU 1.5 mcg/kg/h marked off-label.", "date": "2026-10-07", "id": "f010"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "digoxin", "text": "IV loading dose (8-12 mcg/kg) rests on the earlier check, only the oral label was fetched. Fixed 0.125-0.25 mg maintenance kept as 'common practice'.", "date": "2026-10-07", "id": "f011"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "glycopyrrolate", "text": "Reversal dose written as 0.2 mg IV; the fetched text gives the ratio but not the route.", "date": "2026-10-07", "id": "f012"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "pralidoxime", "text": "DuoDote numbers (600 mg + 2.1 mg; 1 or 3 auto-injectors) kept but not checked against the DuoDote label; 12 g/24 h maximum dropped.", "date": "2026-10-07", "id": "f013"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "ribavirin", "text": "Inhaled RSV (SPAG-2) dosing kept under 'separate Virazole label' but not checked against that label.", "date": "2026-10-07", "id": "f014"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "promethazine", "text": "Label also mentions 'over 20 to 40 minutes' for something the fetch did not show; left out. IV dilution/rate rewritten from the label.", "date": "2026-10-07", "id": "f015"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "amiodarone", "text": "Kept 'Adult 2.2 g in 24 h' as the maximum; the label only says more than 2,100 mg/day raises the hypotension risk.", "date": "2026-10-07", "id": "f016"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "metoprolol", "text": "Oral doses not checked against an oral label (only the IV label was in this pass).", "date": "2026-10-07", "id": "f017"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "verapamil", "text": "Oral doses not checked against the oral label.", "date": "2026-10-07", "id": "f018"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "valsartan", "text": "Adult oral doses not checked; pediatric dose updated to the label.", "date": "2026-10-07", "id": "f019"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "famotidine", "text": "Oral 20-40 mg daily/BID and 80 mg/day max not checked; only the IV label was available.", "date": "2026-10-07", "id": "f020"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "acetazolamide", "text": "Extended-release 500 mg BID, 500 mg IV and injection prep kept from old text; they come from other acetazolamide labels than the tablet label checked.", "date": "2026-10-07", "id": "f021"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "acyclovir", "text": "800 mg PO 5x/day zoster dose kept; it is in the oral label, not the IV label checked.", "date": "2026-10-07", "id": "f022"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "bisacodyl", "text": "10 mg PR dose kept; not in the capsule label checked. 30 mg bowel-prep dose attributed to 'bowel-prep protocol'.", "date": "2026-10-07", "id": "f023"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "budesonide", "text": "Only the nebulizer (Respules) dosing was aligned; Flexhaler, Symbicort and Crohn's doses were not checked.", "date": "2026-10-07", "id": "f024"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "bupropion", "text": "SR 400 mg/day and smoking-cessation 300 mg/day maximums came from the earlier diff, not a fetched SR or Zyban label.", "date": "2026-10-07", "id": "f025"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "carbamazepine", "text": "Under-6 maximum (35 mg/kg/day) left out because the fetched text did not confirm it.", "date": "2026-10-07", "id": "f026"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "ceftaroline", "text": "Pediatric 12 mg/kg q8h (age 2-17, 33 kg or less) is DrugBug's existing number and is not in the label quotes.", "date": "2026-10-07", "id": "f027"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "bivalirudin", "text": "0.2 mg/kg/h for up to 20 h kept as off-label; it came from older labeling, not a guideline.", "date": "2026-10-07", "id": "f028"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "ceftriaxone", "text": "Med school question (mq3) keeps 500 mg IM for gonorrhea as correct; it cites CDC guidance, not the label (label: 250 mg).", "date": "2026-10-07", "id": "f029"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "cetirizine", "text": "OTC Children's Zyrtec label used, so the lower age is now 2 years; prescription syrup labeling once allowed 6 months.", "date": "2026-10-07", "id": "f030"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "clomiphene", "text": "The escalation to 150 mg/day was removed entirely (no guideline source to cite).", "date": "2026-10-07", "id": "f031"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "diazepam", "text": "Rectal gel doses (0.2 mg/kg and pediatric age bands) not checked against the Diastat label.", "date": "2026-10-07", "id": "f032"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "diclofenac", "text": "Gel dose (2-4 g four times a day) not checked against its label.", "date": "2026-10-07", "id": "f033"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "digoxin-immune-fab", "text": "'Use 0.22-micron filter' in the Other field is not in the label.", "date": "2026-10-07", "id": "f034"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "filgrastim", "text": "Administration 'Other' says 'On-body injector (Neulasta)', which is a different drug (pegfilgrastim).", "date": "2026-10-07", "id": "f035"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "dexmethylphenidate", "text": "IR dose came from a generic tablet label (ages 6-17 only), not the setid on file.", "date": "2026-10-07", "id": "f036"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "hydroxyurea", "text": "Hydrea label gives no fixed CML dose; old 15-30 mg/kg/day kept as off-label oncology protocol. Pediatric 20 mg/kg credited to Siklos.", "date": "2026-10-07", "id": "f037"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "hydralazine", "text": "Heart-failure dose and ACOG pregnancy regimen kept as off-label; not checked against the guideline texts.", "date": "2026-10-07", "id": "f038"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "hydrochlorothiazide", "text": "12.5 mg start now marked off-label; some 12.5 mg capsule products may be labeled at that dose.", "date": "2026-10-07", "id": "f039"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "ibuprofen", "text": "Pediatric field not checked against the label.", "date": "2026-10-07", "id": "f040"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "hydrocodone", "text": "Pediatric field not checked; label may say pediatric use is not established.", "date": "2026-10-07", "id": "f041"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "lactulose", "text": "Constipation dose came from a different lactulose label than the encephalopathy dose.", "date": "2026-10-07", "id": "f042"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "liothyronine", "text": "IV myxedema dose came from a separate IV label (setid a8b39730).", "date": "2026-10-07", "id": "f043"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "levetiracetam", "text": "Pediatric maintenance 10-30 mg/kg twice daily kept without checking the label.", "date": "2026-10-07", "id": "f044"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "ketamine", "text": "Pediatric section of the label not checked; field marked off-label (EMS protocol) without a 'not established' statement.", "date": "2026-10-07", "id": "f045"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "labetalol", "text": "Stroke quiz question answer (10-20 mg IV) is the AHA dose, not the label's 20 mg start; kept because the dose field lists it as off-label.", "date": "2026-10-07", "id": "f046"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "metronidazole", "text": "2 g single dose for trichomoniasis taken from generic tablet labels, not the Flagyl 375 capsule label.", "date": "2026-10-07", "id": "f047"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "nafcillin", "text": "6 g/day maximum is a calculation from 1 g every 4 h, not a figure the label states.", "date": "2026-10-07", "id": "f048"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "pancuronium", "text": "openFDA label is from 2017 with no manufacturer; may no longer be marketed in the US.", "date": "2026-10-07", "id": "f049"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "spironolactone", "text": "HTN 25-100 mg and 'avoid CrCl under 30' kept from old text; pediatric written as 'Not in the FDA label'.", "date": "2026-10-07", "id": "f050"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "sildenafil", "text": "ED 'once daily' limit kept from old text, not the label quotes.", "date": "2026-10-07", "id": "f051"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "simvastatin", "text": "'In evening' kept from old text, not the label quotes.", "date": "2026-10-07", "id": "f052"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "tacrolimus", "text": "Pediatric field ('Weight-based') unchanged.", "date": "2026-10-07", "id": "f053"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "testosterone", "text": "Weekly/SQ dosing marked 'Off-label (per Endocrine Society guideline)'; attribution from memory.", "date": "2026-10-07", "id": "f054"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "aminophylline", "text": "Dosing section could not be read; quotes are short Clinical Pharmacology fragments.", "date": "2026-10-07", "id": "f055"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "aminocaproic-acid", "text": "Marked match, but neither label read states DrugBug's 30 g/24 h maximum.", "date": "2026-10-07", "id": "f056"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "acetaminophen", "text": "Only the IV label was checked, not the oral label.", "date": "2026-10-07", "id": "f057"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "amphotericin-b", "text": "Only the conventional product's label was checked, not the liposomal one.", "date": "2026-10-07", "id": "f058"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "nesiritide", "text": "Natrecor label is from 2020; product may no longer be sold.", "date": "2026-10-07", "id": "f059"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "", "text": "Many drug pages cite a repackager's copy of the FDA label (for example Bryant Ranch Prepack, A-S Medication Solutions, Direct_Rx). The wording is the same as the original, but citing the original manufacturer's label looks more authoritative. Ask Claude to switch the label sources to the original makers.", "date": "2026-10-07", "id": "f060"}, {"area": "FDA label alignment", "sev": "medium", "t": "drug", "ref": "", "text": "Many 'Off-label (per ...)' guideline names were chosen by the writing agents from memory (IDSA, ACOG, AHA, PALS, ATA, AASLD, NCCN, Surviving Sepsis, 'pediatric references', 'toxicology references', 'critical care practice'). Check each against the actual guideline.", "date": "2026-10-07", "id": "f061"}, {"area": "Learning boxes", "sev": "low", "t": "blood", "ref": "reactionsteps", "text": "'In the aircraft' tip 'carry spare saline tubing' is not in the source text.", "date": "2026-10-07", "id": "f062"}, {"area": "Learning boxes", "sev": "low", "t": "blood", "ref": "hyperk", "text": "'Keep the cardiac monitor visible' tip is not in the source text.", "date": "2026-10-07", "id": "f063"}, {"area": "Learning boxes", "sev": "low", "t": "blood", "ref": "refusal", "text": "'Document the refusal before you lift' tip is not in the source text.", "date": "2026-10-07", "id": "f064"}, {"area": "Learning boxes", "sev": "low", "t": "blood", "ref": "reversal", "text": "'Medication list is hard to find once airborne' is not in the source text.", "date": "2026-10-07", "id": "f065"}, {"area": "Learning boxes", "sev": "low", "t": "hemo", "ref": "normals", "text": "Mistake line links 25% extraction to SvO2 60-80% ('which is why'); the link is an inference.", "date": "2026-10-07", "id": "f066"}, {"area": "Learning boxes", "sev": "low", "t": "hemo", "ref": "shockprofiles", "text": "Memory line combines the bedside rule with the tank/pump/pipes analogy from another topic.", "date": "2026-10-07", "id": "f067"}, {"area": "Learning boxes", "sev": "low", "t": "hemo", "ref": "impella", "text": "On the wards line shortens the DanGer Shock result (drops '180-day' and 'without coma').", "date": "2026-10-07", "id": "f068"}, {"area": "Learning boxes", "sev": "low", "t": "hemo", "ref": "iabp", "text": "Flight line leaves out the source's helium and altitude detail.", "date": "2026-10-07", "id": "f069"}, {"area": "Learning boxes", "sev": "low", "t": "contrast", "ref": "stresstest", "text": "'Keep aminophylline nearby' is not in the source text.", "date": "2026-10-07", "id": "f070"}, {"area": "Learning boxes", "sev": "low", "t": "contrast", "ref": "rpsafety", "text": "'Keep spill supplies ready' is not in the source text.", "date": "2026-10-07", "id": "f071"}, {"area": "Learning boxes", "sev": "low", "t": "contrast", "ref": "ki", "text": "'Confirm KI on the physician's schedule before MIBG' is not in the source text.", "date": "2026-10-07", "id": "f072"}, {"area": "Learning boxes", "sev": "low", "t": "lab", "ref": "glu", "text": "'Too little starves the brain quickly' is not stated in the glucose text.", "date": "2026-10-07", "id": "f073"}, {"area": "Learning boxes", "sev": "low", "t": "lab", "ref": "na", "text": "Slow-correction point applies to chronic hyponatremia; the source caps correction but does not say 'chronic'.", "date": "2026-10-07", "id": "f074"}, {"area": "Learning boxes", "sev": "low", "t": "lab", "ref": "trophs", "text": "Box shows only the hs-cTnT example cutoff; sex-specific hs-cTnI cutoffs left out.", "date": "2026-10-07", "id": "f075"}, {"area": "Learning boxes", "sev": "low", "t": "lab", "ref": "crpesr", "text": "ESR normal shortened; memory hook 'CRP is the sprinter, ESR is the marathoner' is original.", "date": "2026-10-07", "id": "f076"}, {"area": "Flight Prep", "sev": "medium", "t": "flightp", "ref": "tuc-zones", "text": "Physiologic zone ceiling written as about 10,000 ft (some texts say 12,000). TUC values and hypoxia stage altitudes are commonly cited approximations.", "date": "2026-10-07", "id": "f077"}, {"area": "Flight Prep", "sev": "medium", "t": "flightp", "ref": "dcs-age", "text": "Flying-after-diving waits (12 h single dive, 18 h repetitive) and 'under 1,000 ft above departure' for DCI transport are general rules; protocols vary.", "date": "2026-10-07", "id": "f078"}, {"area": "Flight Prep", "sev": "low", "t": "flightp", "ref": "flight-stresses", "text": "Flicker vertigo 4-20 flashes/s and aircraft noise over 90 dB are approximate teaching values.", "date": "2026-10-07", "id": "f079"}, {"area": "Flight Prep", "sev": "low", "t": "flightp", "ref": "trapped-gas", "text": "ETT cuff pressure 20-30 cmH2O and cuff volume math use 565 mmHg at 8,000 ft; verify against your program's references.", "date": "2026-10-07", "id": "f080"}, {"area": "Flight Prep", "sev": "medium", "t": "flightp", "ref": "cc-trauma", "text": "TXA described as within 3 hours per CRASH-2-based protocols; 'possible harm after 3 hours' is the writer's reading. Parkland example (about 1,070 mL/h) also notes ABLS now starts adults at 2 mL/kg/%TBSA.", "date": "2026-10-07", "id": "f081"}, {"area": "Flight Prep", "sev": "medium", "t": "flightp", "ref": "cc-tbi", "text": "Brain Trauma Foundation BP targets and brief hyperventilation to PaCO2 30-35 written from memory of the guideline.", "date": "2026-10-07", "id": "f082"}, {"area": "Flight Prep", "sev": "low", "t": "flightp", "ref": "cc-shock", "text": "'Norepinephrine generally preferred' in cardiogenic shock and NE over phenylephrine in neurogenic shock follow consensus teaching, not one fixed guideline.", "date": "2026-10-07", "id": "f083"}, {"area": "Flight Prep", "sev": "low", "t": "flightp", "ref": "cc-vent", "text": "ARDSnet, NRP and ACOG values in the critical care challenge were written from memory.", "date": "2026-10-07", "id": "f084"}, {"area": "Launch & legal", "sev": "high", "t": "", "ref": "", "text": "Terms of Use, Privacy Policy and Disclaimers still say 'Draft pending legal review'. Have a lawyer review them before public launch.", "date": "2026-10-07", "id": "f085"}, {"area": "Launch & legal", "sev": "medium", "t": "", "ref": "", "text": "Look into errors and omissions (E&O) or media liability insurance for medical education content.", "date": "2026-10-07", "id": "f086"}, {"area": "Launch & legal", "sev": "medium", "t": "", "ref": "", "text": "All doses were aligned to FDA labels in one fast pass (210 drugs). Review the changed drugs in AI content review and mark each reviewed.", "date": "2026-10-07", "id": "f087"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "doxylamine", "text": "Diclegis (doxylamine-pyridoxine) pregnancy dosing was written from memory; verify against the Diclegis label.", "date": "2026-10-07", "id": "f088"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "cyproheptadine", "text": "Serotonin syndrome dose is off-label (per toxicology references); the cyproheptadine label used is dated 2023.", "date": "2026-10-07", "id": "f089"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "meclizine", "text": "OTC dose assumes 25 mg tablets; check the Drug Facts label of the product you reference.", "date": "2026-10-07", "id": "f090"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "dimenhydrinate", "text": "OTC dose assumes 50 mg tablets; check the Drug Facts label.", "date": "2026-10-07", "id": "f091"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "mometasone", "text": "Nasal polyps dose (2 sprays per nostril twice daily) written from memory; verify against the Nasonex label.", "date": "2026-10-07", "id": "f092"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "olopatadine", "text": "Olopatadine 0.2% and 0.7% eye-drop dosing written from memory; verify against Pataday labels.", "date": "2026-10-07", "id": "f093"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "olopatadine", "text": "Patanase (nasal) label is from 2012 and the product may be discontinued.", "date": "2026-10-07", "id": "f094"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "cromolyn", "text": "Nebulized cromolyn 20 mg four times daily written from memory; nebulizer product may be discontinued in the US.", "date": "2026-10-07", "id": "f095"}, {"area": "New allergy drugs", "sev": "medium", "t": "drug", "ref": "pseudoephedrine", "text": "Extended-release doses and the federal purchase limits (CMEA) were written from memory; verify.", "date": "2026-10-07", "id": "f096"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "ketotifen", "text": "Ketotifen eye-drop minimum age is paraphrased from the Drug Facts label.", "date": "2026-10-07", "id": "f097"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "oxymetazoline", "text": "Tagged for ED, prehospital and trauma use (epistaxis) based on common protocols, not the label.", "date": "2026-10-07", "id": "f098"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "zafirlukast", "text": "Lactation and neuropsychiatric warning wording written from memory.", "date": "2026-10-07", "id": "f099"}, {"area": "New allergy drugs", "sev": "low", "t": "drug", "ref": "", "text": "Off-label lines on the 19 new allergy drugs cite StatPearls from memory; pharmacokinetics and brand lists are general knowledge.", "date": "2026-10-07", "id": "f100"}, {"area": "Question bank", "sev": "medium", "t": "q", "ref": "flight", "text": "130 new hard flight questions: HIET/glucagon/cyproheptadine/albuterol doses, CRASH-2 and WOMAN TXA timing, ACOG magnesium, misoprostol 800 mcg, NRP/PALS/ESETT values, ASRA lipid emulsion, protamine 2.5 h rule, vasopressin 0.07 cap wording are guideline values from memory.", "date": "2026-10-07", "id": "f101"}, {"area": "Question bank", "sev": "low", "t": "q", "ref": "flight", "text": "One flight question assumes andexanet alfa is not carried by the program.", "date": "2026-10-07", "id": "f102"}, {"area": "Question bank", "sev": "medium", "t": "q", "ref": "rn", "text": "90 new hard RN questions: potassium infusion rate is protocol-dependent; DKA dextrose threshold, heparin and norepinephrine drip rates follow common protocols; two items are judgment calls.", "date": "2026-10-07", "id": "f103"}, {"area": "Question bank", "sev": "medium", "t": "q", "ref": "intern", "text": "70 new hard intern questions use guideline doses (acetaminophen 2 g in cirrhosis, 3% saline 100 mL bolus, insulin 0.5 units/kg, 75-80% basal pre-op, ACOG labetalol, AAP amoxicillin 90 mg/kg, MHAUS dantrolene, ACLS magnesium 2 g, CHEST INR). Only 4 are deprescribing questions.", "date": "2026-10-07", "id": "f104"}, {"area": "Question bank", "sev": "low", "t": "q", "ref": "paramedic", "text": "100 easier questions were moved from the flight bank to the paramedic bank. Each scope now only draws its own questions (paramedic and LVN also get the general pool).", "date": "2026-10-07", "id": "f105"}, {"area": "Question bank", "sev": "low", "t": "q", "ref": "", "text": "Questions now randomly show drugs by brand or generic name (fixed list in app.js MIXALT; form-specific brands are skipped). Spot-check that no swap reads wrong.", "date": "2026-10-07", "id": "f106"}, {"area": "FDA label alignment", "sev": "low", "t": "drug", "ref": "", "text": "Special-population lines like 'use if needed' were rewritten to 'prescriber weighs benefit vs risk' (tools/neutral_wording.py, 211 edits). FDA label quotes were left verbatim.", "date": "2026-10-07", "id": "f107"}, {"area": "Question bank", "sev": "low", "t": "q", "ref": "paramedic", "text": "The 100 relabeled questions got new question ids (id = level + text), so any Control Center edits or review notes made on them as flight questions no longer attach.", "date": "2026-10-07", "id": "f108"}, {"area": "Drug Alternatives", "sev": "medium", "t": "", "ref": "alts", "text": "Allergy cross-reactivity notes in Drug Alternatives were written from memory: AAAAI/ACAAI 2022 practice parameter (penicillin/cephalosporin/carbapenem, fluoroquinolones), Strom et al. NEJM 2003 (sulfonamides), AAAAI on NSAID-exacerbated respiratory disease, Haymore 2008 (ARB after ACE-inhibitor angioedema), opioid pseudoallergy. Verify wording and citations.", "date": "2026-10-07", "id": "f109"}, {"area": "Drug Alternatives", "sev": "low", "t": "", "ref": "alts", "text": "Alternatives are computed from DrugBug's class text, drug families, 'Similar Drugs' field and indications, not from a formulary or guideline. Spot-check a few common drugs for odd matches.", "date": "2026-10-07", "id": "f110"}, {"area": "Version 2.1", "sev": "high", "t": "", "ref": "ios", "text": "ContentView.swift (StoreKit + new daily-reminder bridge) could not be compiled here (no Xcode in Claude's workspace). Build it in Xcode first; paste any error to Claude.", "date": "2026-10-07", "id": "f111"}, {"area": "Version 2.1", "sev": "medium", "t": "", "ref": "ios", "text": "Daily study reminder: test on a real iPhone (turn on in Settings > Study, allow notifications, wait for the time).", "date": "2026-10-07", "id": "f112"}, {"area": "Version 2.1", "sev": "medium", "t": "", "ref": "review", "text": "Age-rating answers in 06-App-Review-Notes.md are a suggestion; Apple's questionnaire wording changes. Answer it yourself in App Store Connect.", "date": "2026-10-07", "id": "f113"}, {"area": "Version 2.1", "sev": "low", "t": "", "ref": "ixn", "text": "Interaction checker: new rule 'SSRI or SNRI plus a blood thinner' written from memory of SSRI label bleeding warnings. The checker only covers DrugBug's rule set plus what drug pages mention.", "date": "2026-10-07", "id": "f114"}, {"area": "Version 2.1", "sev": "low", "t": "", "ref": "shop", "text": "Shop prices doubled for bugs, wardrobe items and paid faces (sticks now pay 3 per correct answer). Music tracks stay 500. People who already own items keep them.", "date": "2026-10-07", "id": "f115"}, {"area": "Version 2.1", "sev": "low", "t": "", "ref": "bake", "text": "Control Center edits are baked into the build with tools/bake_edits.py. Only 1 edited drug record existed (activated charcoal); its stale pre-FDA dose fields were also corrected in the live database.", "date": "2026-10-07", "id": "f116"}, {"area": "Version 2.1", "sev": "medium", "t": "", "ref": "pro", "text": "2.1 beta ships with Pro subscriptions switched off (paywall: false in app-config.js): everything free, no paywall. Turn on with paywall: true after the subscriptions are set up; re-test purchases then.", "date": "2026-10-07", "id": "f117"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "medium", "t": "drug", "ref": "", "text": "Peptides: FDA 503A Category 2 listings (2023) and later changes for ipamorelin, CJC-1295, AOD-9604, selank, semax, epitalon, kisspeptin-10 were written from memory; WADA categories also from memory. Verify current status.", "date": "2026-10-07", "id": "f118"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "medium", "t": "drug", "ref": "retatrutide", "text": "Retatrutide phase 2 result (about 24% weight loss at 48 weeks, NEJM 2023) from memory; no phase 3 numbers cited.", "date": "2026-10-07", "id": "f119"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "melanotan-ii", "text": "Melanotan II harm case reports and regulator warnings written from memory.", "date": "2026-10-07", "id": "f120"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "calcitonin-salmon", "text": "Nasal calcitonin label is a 2010 Fortical repackager label; Miacalcin nasal discontinued.", "date": "2026-10-07", "id": "f121"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "setmelanotide", "text": "Imcivree pediatric (2 to under 6 yr) weight table not readable; field says per label table.", "date": "2026-10-07", "id": "f122"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "medium", "t": "drug", "ref": "", "text": "Illicit drugs: DEA scheduling for bromazolam, etizolam (temporary vs permanent), cannabis rescheduling, xylazine, tianeptine and phenibut needs checking; FDA action dates (7-OH 2025, Neptune's Fix 2024, Diamond Shruumz 2024, MDMA CRL 2024) from memory.", "date": "2026-10-07", "id": "f123"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "cocaine", "text": "Goprelto maximum dose read as 160 mg or 3 mg/kg from a truncated fetch; check the full label.", "date": "2026-10-07", "id": "f124"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "ethanol", "text": "Ethanol marked NOT FDA APPROVED with no dose even though dehydrated alcohol injection (Ablysinol) is approved for septal ablation; mentioned in text only.", "date": "2026-10-07", "id": "f125"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "ghb", "text": "Xyrem split-dose timing and pediatric weight-based dosing not quoted exactly from the label.", "date": "2026-10-07", "id": "f126"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "medium", "t": "drug", "ref": "", "text": "Vitamins: NIH ODS RDA and upper limits for vitamins, zinc and magnesium written from memory; folic acid label is a 2015 repackager label.", "date": "2026-10-07", "id": "f127"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "hydrocortisone", "text": "Small-sickness guide links itchy rash to the IV hydrocortisone page; a separate topical hydrocortisone 1% page would fit better.", "date": "2026-10-07", "id": "f128"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "drug", "ref": "phenylephrine", "text": "Statement that FDA proposed removing oral phenylephrine (2024) is from memory.", "date": "2026-10-07", "id": "f129"}, {"area": "Peptides, illicit drugs, vitamins & OTC", "sev": "low", "t": "", "ref": "sick", "text": "Small-sickness guide 'why' text for existing drugs paraphrases their Drug Facts labels from general knowledge, not re-fetched.", "date": "2026-10-07", "id": "f130"}, {"area": "Body map, normals, dose cards", "sev": "low", "t": "", "ref": "body", "text": "Body Systems pearls that need a label check: clozapine REMS removed 2025, teriparatide boxed warning removed 2020, citalopram dose cap, ondansetron 32 mg withdrawal, alteplase 4.5 h window. A few organ placements are judgment calls.", "date": "2026-10-07", "id": "f131"}, {"area": "Body map, normals, dose cards", "sev": "medium", "t": "", "ref": "normals", "text": "Normal vitals: 2025 AHA/ACC BP category names, teen and school-age BP ranges (joined PALS bands), adult SBP 90-119 convention, older-adult temp/SpO2 and capillary refill notes are from memory or convention. Vitamin D, ferritin and NT-proBNP ranges vary by source.", "date": "2026-10-07", "id": "f132"}, {"area": "Body map, normals, dose cards", "sev": "high", "t": "", "ref": "watch", "text": "Dose cards (Apple Watch + web): midazolam 10 mg IM (Seizalam), Diastat bands, naloxone 4 mg nasal details, midazolam infusion and peds values, propofol peds induction, ondansetron peds, ketamine sedation infusion range, fentanyl infusion range, calcium gluconate hyperkalemia dose, PALS atropine minimum, glucagon BB overdose dosing, succinylcholine 1.5 mg/kg (guideline; label 0.6 average), and concentrations used for mL math (norepinephrine 4 mcg/mL, epinephrine 1 mcg/mL, pralidoxime 50 mg/mL) need verification. Labels could not be fetched for this batch.", "date": "2026-10-07", "id": "f133"}, {"area": "Body map, normals, dose cards", "sev": "high", "t": "", "ref": "watch", "text": "Apple Watch app and widget Swift code could not be compiled here (no Xcode). Build in Xcode first and paste any error to Claude.", "date": "2026-10-07", "id": "f134"}, {"area": "Age, disclosure, vials", "sev": "high", "t": "", "ref": "watch", "text": "My vials: the iPhone-to-watch sync (WatchBridge in ContentView.swift, WatchSync in DrugBugWatchApp.swift, WatchConnectivity) is untested and could not be compiled here. Test: set a vial on the phone, open the watch app, confirm '(my vial)' and the mL.", "date": "2026-10-07", "id": "f135"}, {"area": "Age, disclosure, vials", "sev": "medium", "t": "", "ref": "watch", "text": "My vials accept any mg/mcg/g amount and mL a user types; DrugBug does not check them against real vial sizes. mL math is study-only and labeled as such.", "date": "2026-10-07", "id": "f136"}, {"area": "Age, disclosure, vials", "sev": "medium", "t": "", "ref": "legal", "text": "App is now 18+ only: set Apple's age rating to 18+ in App Store Connect (drug references Frequent). Terms/Privacy age text changed; still a draft pending legal review.", "date": "2026-10-07", "id": "f137"}, {"area": "Age, disclosure, vials", "sev": "low", "t": "", "ref": "legal", "text": "Disclosure now shows on every cold start and whenever the app comes back after 15+ seconds in the background (closing the drug page under it temporarily). If testers find that too often, raise DISC_AWAY in legal.js.", "date": "2026-10-07", "id": "f138"}, {"area": "Age, disclosure, vials", "sev": "medium", "t": "", "ref": "print", "text": "iPhone printing (PrintBridge in ContentView.swift, UIPrintInteractionController + UIMarkupTextPrintFormatter) is untested and not compiled here. Check that study cards print two per row; if the layout collapses, switch to a WKWebView viewPrintFormatter.", "date": "2026-10-07", "id": "f139"}, {"area": "Age, disclosure, vials", "sev": "low", "t": "", "ref": "music", "text": "Background music uses WebAudio, which the iPhone silent switch mutes. If testers say music does not play, check the ring/silent switch first.", "date": "2026-10-07", "id": "f140"}, {"area": "Age, disclosure, vials", "sev": "low", "t": "", "ref": "nclex", "text": "Nursing questions now always show generic names; brand-name recognition questions (ones that mention 'brand' or 'generic') keep the brand on purpose.", "date": "2026-10-07", "id": "f141"}, {"area": "Role wording", "sev": "medium", "t": "", "ref": "call", "text": "New 'On a call' lines (DB.CALL, 421 drugs EMS does not give) and 'Why it matters' lines (DB.EXPO, 45 illicit/unapproved, per role) were written by AI from each drug's own fields. Spot-check. Writers flagged small additions beyond the fields: statin rhabdo symptoms (atorvastatin, fluvastatin, lovastatin), ethacrynic acid hearing loss, galantamine bradycardia (borrowed from donepezil), memantine baseline mental status, cipro/levofloxacin/Bactrim lines, bleomycin SpO2 88-92% target, ORS and vitamin D 'ev' lines.", "date": "2026-10-07", "id": "f142"}, {"area": "Role wording", "sev": "low", "t": "", "ref": "call", "text": "Lines that told someone to give a drug were reworded (opioid 'ev' lines now say naloxone can reverse an overdose and 911 can walk you through it; PCP, cocaine, ethanol, vitamin D, vitamin E 'md' lines no longer give treatment orders).", "date": "2026-10-07", "id": "f143"}, {"area": "Role wording", "sev": "high", "t": "", "ref": "call", "text": "Owner rule (2026-10-08): wording must be descriptive education only, no advice or medical decisions (no always/never/must/should, no transport/treatment/disposition calls, no imperatives). DB.CALL and DB.EXPO were rewritten to this rule (tools/callwording/RULES.md). Older content still has similar language: about 130 pearl/home/memory fields, 139 nursing/patient-teaching lines (EXT) and 62 route-wording lines (RW) contain words like always, never, must, should or transport.", "date": "2026-10-07", "id": "f144"}, {"area": "Legal (parked until an attorney reviews)", "sev": "high", "t": "", "ref": "legal", "text": "FDA medical-device question: even as 'education', weight-based dose features (Dose Cards, My vials, Pediatric dosing practice, Apple Watch) could be seen as producing dosing output. They are now framed as simulations for fictional patients with an acknowledgement gate; have a healthcare regulatory attorney review before public launch.", "date": "2026-10-07", "id": "f145"}, {"area": "Legal (parked until an attorney reviews)", "sev": "high", "t": "", "ref": "legal", "text": "Limitation of liability ($50 cap) and Terms bind only users who agree; they may not hold for gross negligence, personal injury, consumer-protection claims or claims by injured third-party patients. Attorney to draft final wording.", "date": "2026-10-07", "id": "f146"}, {"area": "Legal (parked until an attorney reviews)", "sev": "high", "t": "", "ref": "legal", "text": "Get quotes for technology errors & omissions (E&O) insurance that covers educational software with medication content and calculators; tell the insurer about the calculators.", "date": "2026-10-07", "id": "f147"}, {"area": "Legal (parked until an attorney reviews)", "sev": "medium", "t": "", "ref": "legal", "text": "Arbitration and class-action waiver not added (attorney decision). Venue clause added: Texas law, Brazos County courts; confirm the LLC is organized in Texas and the county is right.", "date": "2026-10-07", "id": "f148"}, {"area": "Legal (parked until an attorney reviews)", "sev": "medium", "t": "", "ref": "legal", "text": "Written reviewer agreements for any physician/pharmacist/nurse/paramedic reviewers (IP ownership, duties, pay, confidentiality, liability). Terms do not protect reviewers.", "date": "2026-10-07", "id": "f149"}, {"area": "Legal (parked until an attorney reviews)", "sev": "medium", "t": "", "ref": "legal", "text": "Classes and leaderboard parked (DRUGBUG_CONFIG.social): FERPA obligations when processing student records for a school need review before turning them back on.", "date": "2026-10-07", "id": "f150"}, {"area": "Legal (parked until an attorney reviews)", "sev": "medium", "t": "", "ref": "legal", "text": "Privacy Policy needs attorney review (learner scores, analytics, Firebase, deletion and retention, state privacy laws). Auto-renewal law compliance for subscriptions (California etc.) to confirm.", "date": "2026-10-07", "id": "f151"}, {"area": "Legal (parked until an attorney reviews)", "sev": "low", "t": "", "ref": "legal", "text": "LLC liability shield is not absolute; keep business and personal finances separate and keep records of clinical reviews and software testing (tools/test_dosecalc.js: 380 checks).", "date": "2026-10-07", "id": "f152"}, {"area": "Conditions lookup", "sev": "medium", "t": "", "ref": "conds", "text": "Conditions & Medicine Cautions matches conditions to drugs by keyword search of each drug's contraindication, warning and special-population fields (modules/conditions.js CONDS). Keyword matching can over- or under-include (e.g. hypertension vs pulmonary hypertension handled; others may slip). Spot-check a few conditions. Education-only wording, nothing saved.", "date": "2026-10-07", "id": "f153"}, {"area": "Launch", "sev": "low", "t": "", "ref": "pro", "text": "Free trial switched to Apple's rules: 1-week free introductory offer on Pro Monthly and Pro Yearly (set up in App Store Connect). The app-run 7-day period was removed. Users start on Free.", "date": "2026-10-07", "id": "f154"}, {"area": "Launch", "sev": "high", "t": "", "ref": "pro", "text": "Before submitting: Paid Apps agreement active, four products created (1-week free intro offer on the two Pro products, Family Sharing off), website live with real URLs in app-config.js site and the listing, Privacy Policy URL set. Without the products the plans screen shows 'Loading prices'.", "date": "2026-10-07", "id": "f155"}, {"area": "Security & accounts", "sev": "high", "t": "", "ref": "security", "text": "Accounts (2.2) are built but untested against a live Firebase project and not compiled (Sign in with Apple bridge in ContentView.swift). Run the 8 two-account security tests in launch-kit/10-Accounts-Setup-2.2.md before turning accounts on.", "date": "2026-10-07", "id": "f156"}, {"area": "Security & accounts", "sev": "medium", "t": "", "ref": "security", "text": "Apple token revocation on account deletion relies on the Firebase web SDK's revokeAccessToken; if unavailable in the bundled version, add a Cloud Function that calls Apple's revoke endpoint (Apple requires revocation for Sign in with Apple account deletion).", "date": "2026-10-07", "id": "f157"}, {"area": "Security & accounts", "sev": "medium", "t": "", "ref": "security", "text": "Classroom redesign still needed before Classes return: instructors must only read rosters of students enrolled in classes they own (membership-checked rules). Legacy class records are now private to their owner.", "date": "2026-10-07", "id": "f158"}, {"area": "Security & accounts", "sev": "low", "t": "", "ref": "security", "text": "Firestore rules cap document size and validate leaderboard fields, but XP values are still self-reported; consider server-side scoring (Cloud Function) if the leaderboard returns.", "date": "2026-10-07", "id": "f159"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "hydrocortisone-cream", "text": "New OTC monograph (Hydrocortisone Cream 1%) drafted from the Cortizone-10 Drug Facts label (DailyMed setid bb3d1a3e…, Sep 2025). Review wording, uses list and pediatric/ pregnancy lines. Sick guide 'Itchy rash and bug bites', body map skin, OTC group now link here instead of IV hydrocortisone.", "date": "2026-10-07", "id": "f160"}, {"area": "1.1 update", "sev": "low", "t": "", "ref": "spanish", "text": "Spanish UI: 'bicho/bichos' (vulgar in Puerto Rico) replaced with 'insecto/insectos'; 'pico' (vulgar in Chile) replaced in 3 lines of es4; 'orina color cola' -> 'orina muy oscura'. 'huevo' (egg allergy) kept as the standard term. A native-speaker review of all Spanish text is still recommended.", "date": "2026-10-07", "id": "f161"}, {"area": "1.1 update", "sev": "high", "t": "drug", "ref": "oncology", "text": "315 new monographs (290 cancer drugs + supportive care, 5 US antivenoms, 23 international antivenoms) drafted by AI agents from DailyMed labels (data/gen29-33, ext21-25, es18-22, rw13-17, lbl7-11, call2-6). Adult doses match the quoted label text, but many PK values, contraception/lactation windows, renal/hepatic wording and monitoring schedules are from memory and need a pharmacist/oncology review before marketing them as reviewed.", "date": "2026-10-07", "id": "f162"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "necitumumab", "text": "No DailyMed label (lbl nl:1) but the monograph lists the Lilly USPI dose (800 mg Days 1 and 8). Portrazza may be discontinued in the US; consider removing the dose or the drug.", "date": "2026-10-07", "id": "f163"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "sunvozertinib", "text": "Zegfrovy dose (200 mg daily) taken from drugs.com copy of the FDA label; no DailyMed setid found yet (lbl nl:1). Add the setid when DailyMed lists it.", "date": "2026-10-07", "id": "f164"}, {"area": "1.1 update", "sev": "low", "t": "drug", "ref": "ofatumumab", "text": "Arzerra (CLL) has no current US label; entry uses the Kesimpta (MS) label dose. Listed in the oncology antibody group for history only.", "date": "2026-10-07", "id": "f165"}, {"area": "1.1 update", "sev": "low", "t": "drug", "ref": "samarium-sm-153-lexidronam", "text": "Quadramet appears discontinued; no DailyMed label, no doses shown.", "date": "2026-10-07", "id": "f166"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "antivenoms-intl", "text": "23 international antivenoms: NOT FDA approved, no doses. Species coverage, F(ab')2 vs IgG and licensing country partly from memory (see agent notes): ViperaTAb licensing wording, QSMI F(ab')2, Inoserp equine source.", "date": "2026-10-07", "id": "f167"}, {"area": "1.1 update", "sev": "low", "t": "", "ref": "weird-drug-wednesday", "text": "Weird Drug Wednesday (modules/wdw.js, data/wdw1.js, 52 facts): on by default; iOS/Android schedule the next 12 Wednesdays as local notifications at 12:00. Facts written by an agent from general knowledge; two sources are Wikipedia (taipan, boomslang).", "date": "2026-10-07", "id": "f168"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "probiotics", "text": "35 probiotic entries (33 supplement strains/products, no doses; Rebyota and Vowst with DailyMed labels) + Probiotics strain explorer (Everyday Health, Plus; data/probio1.js DB.PROBIO with evidence ratings strong/some/mixed/early/none). Agents could not open PubMed/PMC; several trial numbers are from memory (see build notes v98). Evidence ratings are judgment calls and need expert review.", "date": "2026-10-07", "id": "f169"}, {"area": "1.1 update", "sev": "high", "t": "drug", "ref": "general-expansion", "text": "429 more monographs (1,354 total) across cardio, diabetes, endocrine, GI, ID/HIV/hepatitis, neuro (seizure, migraine, MS, Parkinson), psych, pulmonary, rheum/biologics, derm, ophtho, urology, hematology, toxicology antidotes, anesthesia, women's health, 21 vaccines, immune globulins, IV fluids and 17 rare-disease drugs (gen35-39, ext27-31, es24-28, rw19-23, lbl13-17, call8-12). Adult doses match DailyMed quotes; many labels are generic/repackager copies (originator unavailable or rate-limited) and some quotes were joined from fragments. PK values and some renal/hepatic steps are from memory. Pharmacist review advised.", "date": "2026-10-07", "id": "f170"}, {"area": "1.1 update", "sev": "medium", "t": "drug", "ref": "no-label-2", "text": "No current US drug label (nl 1): lactase (supplement), piperacillin (single agent discontinued), artesunate (label exists, DailyMed setid not found; dose from FDA PDF), brexanolone (Zulresso discontinued), hypertonic saline inhaled (510(k) device; study regimen), boric acid vaginal (unapproved), oral glucose gel (ADA guideline dose).", "date": "2026-10-07", "id": "f171"}, {"area": "1.1 update", "sev": "low", "t": "", "ref": "ems-new", "text": "New EMS/CCT drugs without a call line and added to prehospital groups: normal saline, lactated Ringer's, oral glucose gel, epinephrine nasal (Neffy), plasma-lyte, 3% saline, albumin, PCC (Kcentra), DuoDote, sodium nitrite, sodium thiosulfate. EMS scope notes (scope.js) not yet written for them.", "date": "2026-10-07", "id": "f172"}];

;
/* Control Center edits baked in by tools/bake_edits.py */
DB.BAKED = {"drugdex": [{"cites": ["FDA prescribing information (DailyMed): Activated Charcoal", "NCBI StatPearls: Activated Charcoal", "National EMS Scope of Practice Model (2019)"], "edu": "This medicine is a black liquid that binds poisons in the stomach so less is absorbed. It may cause vomiting and will turn your stools black for a few days. Tell staff right away if you feel drowsy or have trouble swallowing.", "f": {"adm.administrationRate": "Drink slowly over several minutes", "adm.compatibleFluids": "Water only", "adm.dilutionPreparation": "Premixed aqueous slurry; shake well. Avoid sorbitol-containing products in children or repeated doses.", "adm.other": "NG/OG tube in intubated patients", "adm.routes": "PO, NG/OG tube", "adm.specialAdministrationInstructions": "Use a covered cup with a straw to improve acceptance; keep patient upright.", "bd.whatItDoes": "Binds (adsorbs) many drugs and toxins in the GI tract so they are not absorbed into the blood.", "bd.whatItIs": "A fine black powder of highly porous carbon given as a drinkable slurry.", "bd.whyItIsUsed": "GI decontamination after selected recent toxic oral ingestions.", "ci.absoluteContraindications": "Unprotected airway or altered mental status without intubation; GI obstruction or perforation; caustic (acid/alkali) ingestion; hydrocarbon ingestion (aspiration risk)", "ci.relativeContraindications": "Poorly adsorbed substances (iron, lithium, alcohols, metals, cyanide, acids/alkalis); vomiting; patients needing endoscopy; ileus", "di.alcoholInteraction": "None", "di.drugClassesToAvoid": "Do not give with other oral meds within 2 h if avoidable", "di.foodInteractions": "Milk, ice cream, or syrups reduce adsorptive capacity", "di.importantCombinationEffects": "Sorbitol cathartic combinations cause fluid and electrolyte loss (avoid in children)", "di.majorDrugInteractions": "Binds oral medications given at the same time (including oral antidotes like NAC if given orally)", "dose.adultDose": "FDA label (Actidose-Aqua, OTC): 20-30 g PO in at least 8 oz of liquid. Off-label (per toxicology practice): 1 g/kg PO (typically 50-100 g)", "dose.hepaticDoseAdjustment": "None", "dose.maximumDose": "Label: 20-30 g per dose. Off-label (toxicology practice): 100 g single dose in adults", "dose.pediatricDose": "No pediatric dose in FDA label. Off-label (per toxicology practice): 1 g/kg PO (typically 10-50 g); under 1 yr 0.5-1 g/kg", "dose.renalDoseAdjustment": "None", "dose.repeatDose": "Off-label: multi-dose 0.5 g/kg every 4 h (toxicologist directed)", "dose.weightBasedDose": "Off-label (per toxicology practice): 1 g/kg", "home.whatDiseaseDoesThisSuggest": "Not a home medication (may be in poison kits).", "home.whatEmergencyCouldThisMedicationContributeTo": "Not applicable", "home.whatHappensIfTheySuddenlyStopTakingIt": "Not applicable", "home.whatShouldEMSAskAbout": "What was ingested, how much, when.", "home.whyMightMyPatientBeTakingIt": "Rarely kept at home.", "id.brandName": "Actidose-Aqua, CharcoAid, Insta-Char, EZ-Char", "id.commonEMSName": "Charcoal, AC", "id.controlledSubstanceSchedule": "Not controlled", "id.drugClass": "Adsorbent / GI decontaminant", "id.genericName": "Activated charcoal", "id.pharmacologicClass": "Adsorbent", "ind.eMSPrehospitalIndications": "Oral overdose in an awake, alert patient with a protected airway per poison control or medical control", "ind.offLabelUses": "Selected sustained-release ingestions beyond 1 h per toxicologist", "ind.otherCommonIndications": "Multi-dose for carbamazepine, phenobarbital, dapsone, quinine, theophylline", "ind.primaryIndications": "Recent (typically within 1 h) ingestion of a potentially toxic amount of an adsorbable substance", "mem.commonlyConfusedWith": "Ipecac (old emetic, no longer used)", "mem.keyFact": "Only give to an awake patient who can protect their airway.", "mem.memoryTrick": "Charcoal is a sponge: it soaks up pills, not PHAILS.", "mem.mostTestedFact": "Does not bind iron, lithium, alcohols, acids, alkalis, or hydrocarbons.", "mem.oneSentenceSummary": "Activated charcoal adsorbs many oral toxins when given early to a patient who can protect their airway.", "mem.oppositeReversalDrug": "None", "mem.similarDrugs": "Whole-bowel irrigation (PEG solution) for iron/lithium/packets", "mem.simpleExplanation": "A black drink that soaks up some poisons in the stomach before the body absorbs them.", "moa.agonistAntagonistInhibitor": "Not receptor-based (physical adsorbent)", "moa.mechanismOfAction": "Huge surface area adsorbs toxin molecules in the gut lumen, preventing absorption; multi-dose regimens enhance elimination by gut dialysis (interrupting enterohepatic circulation).", "moa.physiologicEffects": "Reduced systemic absorption of the ingested toxin.", "moa.receptorTarget": "Toxins within the GI lumen", "mon.bloodPressure": "Monitor for hypotension related to the ingestion", "mon.eCG": "Monitor ECG for the ingested toxin (TCA, etc.)", "mon.etCO2": "In intubated patients via OG", "mon.heartRate": "Monitor for toxin-related changes", "mon.labs": "Toxicology labs per ingestion", "mon.neurologicStatus": "Must remain alert with intact gag/airway", "mon.otherMonitoring": "Abdominal distension; bowel sounds", "mon.respiratoryStatus": "Assess for vomiting and aspiration", "mon.spO2": "Watch for aspiration", "pearl.commonMedicationErrors": "Giving to a drowsy patient; giving for caustics, hydrocarbons, iron, lithium, or alcohols.", "pearl.dangerousCombinations": "Giving with oral antidotes or with sorbitol repeatedly in children.", "pearl.highYieldClinicalPearl": "PHAILS does not bind: Pesticides (some), Hydrocarbons, Acids/Alkalis/Alcohols, Iron, Lithium, Solvents.", "pearl.whatEMSShouldKnow": "It is not a universal antidote. Many states have removed it from EMT scope; consult poison control (1-800-222-1222).", "pearl.whatToCheckBeforeGiving": "Time and substance ingested, mental status, gag reflex/airway protection, vomiting.", "pearl.whatToMonitorAfterGiving": "Airway, vomiting, aspiration, mental status changes.", "pearl.whenToStopAdministration": "Decreasing mental status or vomiting with aspiration risk.", "pearl.whyEMSGivesIt": "Prevents absorption of some ingested poisons when given early.", "pk.duration": "Remains in gut until excreted", "pk.elimination": "Feces (black stools)", "pk.halfLife": "Not absorbed", "pk.metabolism": "Not metabolized", "pk.onset": "Immediate (binds on contact)", "pk.peak": "Not applicable", "pk.proteinBinding": "Not absorbed", "se.commonSideEffects": "Black stools, vomiting, constipation", "se.lifeThreateningAdverseEffects": "Aspiration with ARDS; bowel perforation", "se.seriousSideEffects": "Aspiration pneumonitis, bowel obstruction", "sp.geriatrics": "Higher aspiration risk", "sp.hepaticImpairment": "No adjustment", "sp.lactation": "Safe; not absorbed", "sp.pediatrics": "Use only with protected airway; avoid sorbitol", "sp.pregnancy": "Safe; not absorbed", "sp.renalImpairment": "No adjustment", "tox.antidote": "None", "tox.overdosePresentation": "Aspiration pneumonitis if given to an obtunded patient", "tox.overdoseTreatment": "Supportive airway management; bowel care", "tox.reversalAgent": "None", "tox.signsOfToxicity": "Vomiting, constipation, obstruction with large repeated doses", "tox.toxicDoseToxicity": "Not toxic itself", "wp.boxedWarning": "None", "wp.importantPrecautions": "Does not bind alcohols, metals (iron, lithium, lead), acids, alkalis, or hydrocarbons (remember PHAILS). Can make the patient vomit.", "wp.majorWarnings": "Aspiration of charcoal can cause severe pneumonitis and ARDS."}, "groups": ["EMS Toxicology / Antidotes"], "id": "activated-charcoal", "name": "Activated Charcoal", "nurse": "Confirm the patient has an intact or protected airway and a recent ingestion (ideally within 1 hour); do not give for caustics, hydrocarbons, alcohols, iron or lithium, or with ileus or bowel obstruction; keep the head of bed elevated and have suction ready because aspiration is the main risk; avoid sorbitol-containing products for repeat doses; separate from other oral medicines it will adsorb.", "rev": 2, "review": {"by": "Adam Ficklen", "cred": "EMT-P, FP-C", "date": "2026-10-06", "status": "reviewed"}, "status": "published", "tags": ["PH", "ED", "PE", "TX", "AD"], "updatedAt": 1791319013903, "updatedBy": "u_48X1K3mgaXc9xRo_XlRpNA"}], "content": []};

